CREATE TABLE IF NOT EXISTS calls(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES conversations(id),caller_id uuid NOT NULL,callee_id uuid NOT NULL,status text NOT NULL DEFAULT 'ringing' CHECK(status IN ('ringing','accepted','declined','ended')),created_at timestamptz NOT NULL DEFAULT now(),ended_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS one_active_call ON calls(conversation_id) WHERE status IN ('ringing','accepted');
CREATE TABLE IF NOT EXISTS call_feedback(call_id uuid NOT NULL REFERENCES calls(id),account_id uuid NOT NULL,experience text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(call_id,account_id));
CREATE TABLE IF NOT EXISTS date_plans(id uuid PRIMARY KEY,conversation_id uuid NOT NULL REFERENCES conversations(id),proposer_id uuid NOT NULL,venue text NOT NULL,address text NOT NULL,scheduled_at timestamptz NOT NULL,budget_inr integer NOT NULL,status text NOT NULL DEFAULT 'invited' CHECK(status IN ('invited','accepted','declined','cancelled')),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS date_checkins(id uuid PRIMARY KEY,plan_id uuid NOT NULL REFERENCES date_plans(id),account_id uuid NOT NULL,state text NOT NULL,note text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
